function MC_Game:missiles_add ()
    local missile = Missile:new({
        x = math.random(0, PLAY_WIDTH),
        y = 0,
        target_x = math.random(0, PLAY_WIDTH),
        target_y = PLAY_HEIGHT-10,
        speed = MISSILE_SPEED
    })
    table.insert(self.missiles, missile)
    trace("Current missiles: ")
