-- Constants
TILE_SIZE = 16
GRID_WIDTH = 7
GRID_HEIGHT = 8

-- Select mode is moving the select around.
-- swap mode is picking a direction to swap two tiles.
InputModes = Enum("Select", "Swap")

M3_Game = {}

function M3_Game:new ()
   o = {
      grid = Grid:new(GRID_WIDTH, GRID_HEIGHT),
      selected = Pt:new{x = math.ceil(grid.width/2), y = grid.height/2},
      input_mode = InputModes.Select,
      particles = {},
   }
   setmetatable(o, self)
   self.__index = self
   return o
end

-- Variables
grid = Grid:new(GRID_WIDTH, GRID_HEIGHT) --{height=GRID_HEIGHT, width=GRID_WIDTH}

function tprint (tbl, indent)
  if not indent then indent = 0 end
  for k, v in pairs(tbl) do
    formatting = string.rep("  ", indent) .. k .. ": "
    if type(v) == "table" then
      trace(formatting)
      tprint(v, indent+1)
    elseif type(v) == 'boolean' then
      trace(formatting .. tostring(v))
    elseif type(v) == 'function' then
      trace(formatting .. "func")
    else
      trace(formatting .. v)
    end
  end
end

local part_sprs = {5, 7, 9, 11}

tile_sprs = {
   160,
   162,
   192,
   194,
   224,
   226,
}
trace("TS:")
tprint(tile_sprs, 2)

function new_part(p)
   return {
      x=p.x,
      y=p.y,
      life=12
   }
end

-- Draw the grid
function M3_Game:grid_draw()
   -- trace("gd")
   -- tprint(self.grid, 1)
   self.grid:test()
   for y=1, self.grid.height do
      for x=1, self.grid.width do
	 local tile = self.grid[y][x]
	 local orig_x = (x-1)*TILE_SIZE
	 local orig_y = (y-1)*TILE_SIZE
	 --trace(y .. ' ' ..  x .. ' ' .. tile)
	 local tile_grp = tile_sprs[tile]
	 --trace(tile .. " " .. tile_grp)
	 spr(tile_grp, orig_x+120, orig_y, 1, 1, 0, 0,2,2)

	 if self.selected.x == x and self.selected.y == y then
	    local color = 13
	    --trace("selected: " .. x .. " " .. y .. " " .. self.grid[y][x] .. " " .. tile_sprs[self.grid[y][x]])
	    if self.input_mode == InputModes.Swap then
	       color = 4
	    end
	    rectb(orig_x+120, orig_y, TILE_SIZE, TILE_SIZE, color)

	 end
      end
   end
end

-- Select tile
function M3_Game:select_tile(dx, dy)
   local new_x = self.selected.x + dx
   if new_x < 1 then
      new_x = 1
      return
   end
   if new_x > self.grid.width then
      new_x = self.grid.width
      return
   end

   local new_y = self.selected.y + dy
   if new_y < 1 then
      new_y = 1
      return
   end
   if new_y > self.grid.height then
      new_y = self.grid.height
      return
   end

   local new_selected = Pt:new(new_x, new_y)

   trace('sels: ' .. tostring(self.selected) .. ' ' .. tostring(new_selected) )

   if self.input_mode == InputModes.Select then
      self.selected = new_selected
   elseif self.input_mode == InputModes.Swap then
      self.input_mode = InputModes.Select

      local ret = self.grid:allow_swap(self.selected, new_selected)
      local allowed = ret[1]
      local matches = ret[2]
      trace('allow?: ' .. tostring(allowed) .. ' ' .. tostring(matches))
      if allowed then
	 self.grid:swap(self.selected, new_selected)
	 for i, m in pairs(matches) do
	    table.insert(self.particles, new_part(m))
	 end
	 self.grid:remove_matches(matches)
	 self.events:emit('bullet', 0)
      end
      self.selected=new_selected
   else
      -- error
   end
end

function M3_Game:move_up ()
   self:select_tile(0, -1)
end

function M3_Game:move_down ()
   self:select_tile(0, 1)
end

function M3_Game:move_left ()
  self:select_tile(-1, 0)
end

function M3_Game:move_right ()
   self:select_tile(1, 0)
end

function mod(a, b)
   return a - math.floor(a/b)*b
end

function M3_Game:draw ()
   self:grid_draw()
   if #self.particles > 0 then
      trace('drawing m3 particles: ' .. #self.particles)
      for i, m in pairs(self.particles) do
	 local orig_x = (m.x-1)*TILE_SIZE
	 local orig_y = (m.y-1)*TILE_SIZE
	 local part_num =  mod(m.life, #part_sprs)
	 local tile_grp = part_sprs[m.life]
	 --trace(tile .. " " .. tile_grp)
	 spr(tile_grp, orig_x+120, orig_y, -1, 1, 0, 0,2,2)
	 m.life = m.life -1
	 if m.life == 0 then
	    table.remove(self.particles, i)
	 end
      end
   end
end

function M3_Game:init (events)
   self.events = events
   self.grid:init(6)
   self.grid:test()
   local clean = self.grid:find_matches()
   if #clean then
      self.grid:remove_matches(clean)
   end
   self.grid:test()
end
-- END m3_lib.lua

-- BEGIN main.lua

-- Game States
GameStates = Enum("StartScreen", "Playing", "GameOver")
current_state = GameStates.StartScreen

mc = {}
m3 = {}
events = Events:new()

function TIC()
    handle_input()
    
    if current_state == GameStates.StartScreen then
        draw_start_screen()
    elseif current_state == GameStates.Playing then
        mc:update()
        cls(0)
        mc:draw()
        m3:draw()
    end
end

function draw_start_screen()
   cls(0)
   
   -- Draw title using text
   local title = "BUBBLE REACTOR DEFENCE"
   local title_x = 120 - (#title * 6) // 2
   print(title, title_x, 40, 12)
   
   -- Draw subtitle
   local subtitle = "Match-3 meets Missile Command"
   local subtitle_x = 120 - (#subtitle * 6) // 2
   print(subtitle, subtitle_x, 60, 6)
   
   -- Draw instructions
   print("Use arrow keys to move", 60, 90, 15)
   print("Press Z to select/swap", 60, 100, 15)
   print("Match 3+ tiles to fire!", 60, 110, 15)
   
   -- Draw start prompt (with blinking effect)
   if math.floor(time() / 500) % 2 == 0 then
      local start_text = "PRESS Z TO START"
      local start_x = 120 - (#start_text * 6) // 2
      print(start_text, start_x, 130, 14)
   end
end

function start_game()
   current_state = GameStates.Playing
   mc = MC_Game:new()
   m3 = M3_Game:new()
   mc:init(events)
   m3:init(events)
end

function BOOT()
   current_state = GameStates.StartScreen
end

-- Handle input
function handle_input()
    if current_state == GameStates.StartScreen then
        if btnp(4) then -- Z key to start
            start_game()
        end
    elseif current_state == GameStates.Playing then
        if btnp(0) then -- Up
            m3:move_up()
        elseif btnp(1) then -- Down
            m3:move_down()
        elseif btnp(2) then -- Left
            m3:move_left()
        elseif btnp(3) then -- Right
            m3:move_right()
        elseif btnp(4) then -- Select -- Z
            if m3.input_mode == InputModes.Select then
                m3.input_mode = InputModes.Swap
            else
                m3.input_mode = InputModes.Select
            end
        end
    end
end
-- END main.lua

